const keys = Object.keys(catalog).sort((a, b) => b.length - a.length);
const pattern = new RegExp(keys.map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'g');
export const intlLocale = (locale) => ({ zh: 'zh-CN', en: 'en-GB', fr: 'fr-FR' }[locale]);
export function translate(text, locale) {
    if (locale === 'zh')
        return text;
    return text.replace(pattern, key => catalog[key][locale]);
}
export function translateParts(locale, parts, values) {
    return parts.reduce((out, part, i) => out + translate(part, locale) + (i < values.length ? String(values[i]) : ''), '');
}
